   '// ---- Riverpod ----\nclass Penghitung extends Notifier<int> {\n  @override\n  int build() => 0;\n  void tambah() => state++;\n}\nfinal penghitungProvider = NotifierProvider<Penghitung, int>(Penghitung.new);\n\nclass HalamanAngka extends ConsumerWidget {\n  const HalamanAngka({super.key});\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final angka = ref.watch(penghitungProvider);\n    return TextButton(\n      onPressed: () => ref.read(penghitungProvider.notifier).tambah(),\n      child: Text(\'Angka: $angka\'),\n    );\n  }\n}\n// main: runApp(const ProviderScope(child: MyApp()));\n\n// ---- Cubit (flutter_bloc) ----\nclass SaldoCubit extends Cubit<int> {\n  SaldoCubit() : super(0);\n  void isi(int n) => emit(state + n);\n}\n// BlocBuilder<SaldoCubit, int>(builder: (context, saldo) => Text(\'$saldo\'))',
